const queued = $input.first().json;
const webhook = $('Incoming Job Lead').first().json;
const lead = webhook.body || webhook;
return [{
  json: {
    ...lead,
    queue_id: queued.queue_id || '',
    queue_status: queued.status || 'unknown',
    duplicate: queued.duplicate === true,
    queue_message: queued.message || '',
    next_step: 'Run the local queue worker to score jobs and export application packets.',
    worker_command: '.\\.venv\\Scripts\\python.exe scripts\\process_job_queue.py --limit 5 --output-root data\\outputs\\queue_packets',
    queued_at: new Date().toISOString(),
  },
}];
